import Foundation
import Observation

/// What the screens know of the person: whether they are signed in, the permissions they hold, and their roles when the session names them.
public struct Session: Sendable, Equatable {
    public var signedIn: Bool
    public var permissions: [String]
    public var roles: [String]

    public init(signedIn: Bool, permissions: [String], roles: [String] = []) {
        self.signedIn = signedIn
        self.permissions = permissions
        self.roles = roles
    }
}

/// Whether a page opens, sends the person to sign in first, or is refused.
public enum Decision: Sendable {
    case allowed, signIn, refused
}

/// The decision for a page that needs a permission, the one the menu reads too.
public enum Access {
    public static func decide(permission: String, session: Session) -> Decision {
        if permission == "public" {
            return .allowed
        }
        if !session.signedIn {
            return .signIn
        }
        if permission == "signedIn" {
            return .allowed
        }
        return session.permissions.contains(permission) ? .allowed : .refused
    }

    /// The permissions the person holds, signedIn among them once signed in.
    public static func held(_ session: Session?) -> [String] {
        guard let session else {
            return []
        }
        return session.signedIn ? session.permissions + ["signedIn"] : session.permissions
    }

    /// The person's home: that of the first of their roles, in the session's order, that has one.
    public static func home(_ homes: [String: Route], session: Session) -> Route? {
        session.roles.lazy.compactMap { homes[$0] }.first
    }

    /// The menu as a person sees it: only the entries whose page opens to them, and no empty group.
    public static func visibleMenu(_ menu: [MenuGroup], session: Session) -> [MenuGroup] {
        menu.map { group in
            MenuGroup(title: group.title, items: group.items.filter { decide(permission: $0.permission, session: session) == .allowed })
        }.filter { !$0.items.isEmpty }
    }
}

/// The person's session, read once from the service and shared by every
/// part of the screens; read again after signing in.
@MainActor
@Observable
public final class SessionStore {
    public static let shared = SessionStore()

    /// The session, nil while it is read.
    public private(set) var current: Session?
    /// True when the service could not be asked, so no page opens.
    public private(set) var failed = false
    private var reading = false
    private var generation = 0

    /// Reads the session, once; a second call while one reads waits for it.
    public func read() async {
        if reading || current != nil {
            return
        }
        reading = true
        let begun = generation
        let answer = await ask()
        reading = false
        if begun != generation {
            await read()
            return
        }
        failed = answer == nil
        current = answer ?? Session(signedIn: false, permissions: [])
    }

    private func ask() async -> Session? {
        guard let settings = Application.session else {
            return Session(signedIn: false, permissions: [])
        }
        do {
            let answer = try await Service.send("GET", settings.path)
            guard answer.ok, let body = answer.body else {
                return nil
            }
            let held = body[settings.permissions]?.items.compactMap { item -> String? in
                if case .string(let s) = item { return s }
                return nil
            } ?? []
            let roles = settings.roles.flatMap { body[$0]?.items.compactMap { item -> String? in
                if case .string(let s) = item { return s }
                return nil
            } } ?? []
            return Session(signedIn: body[settings.signedIn] == .bool(true), permissions: held, roles: roles)
        } catch {
            return nil
        }
    }

    /// Reads the session again, as after signing in.
    public func forget() {
        generation += 1
        current = nil
        failed = false
    }
}
